SELECT cs.canonical_smiles, md.chembl_id AS molecule_chembl_id, act.standard_type, act.standard_relation, act.standard_value, act.standard_units FROM activities act INNER JOIN assays a ON act.assay_id = a.assay_id INNER JOIN molecule_dictionary md ON act.molregno = md.molregno INNER JOIN compound_structures cs ON md.molregno = cs.molregno WHERE a.chembl_id = 'CHEMBL1217643' AND act.standard_relation = '=' AND act.standard_value IS NOT NULL AND act.standard_relation IS NOT NULL ORDER BY cs.canonical_smiles, md.chembl_id, act.standard_type, act.standard_relation, act.standard_value, act.standard_units
